CNT = [0]


def chk(fn):
    r = fn()
    rs = list(r) if isinstance(r, tuple) else [r]
    assert all(rs), ('numeric check failed', rs)
    CNT[0] += len(rs)


def with_img(q, svg):
    q['img'] = svg
    return q


def lin(f, a, dx):
    """f(a+dx) via the differential, and the exact value."""
    mp.mp.dps = 40
    a = mp.mpf(a)
    return f(a) + D(f, a) * mp.mpf(dx), f(a + mp.mpf(dx))


# ----------------------------------------------------------------------------- figures
def fig_vol():
    kx, ky = 18.0, 0.0475
    V = lambda r: 4 / 3 * math.pi * r ** 3
    tg = lambda r: V(10) + 4 * math.pi * 100 * (r - 10)
    return G(300, 230, [(curve(V, kx, ky), 0, 12 * kx, K.BLUE), (curve(tg, kx, ky), 6 * kx, 12 * kx, K.GREEN)], xt=[(kx * v, str(v)) for v in (2, 4, 6, 8, 10, 12)], yt=[(ky * 1000 * k, '%d' % (1000 * k)) for k in (2, 4)],
             dots=[(10 * kx, V(10) * ky, '', 0, 0, K.RED)], xlabel='r', ylabel='V', pad=46)


def fig_cost_tan():
    kx, ky = 2.0, 0.17
    C = lambda t: 0.02 * t ** 2 + 4 * t + 300
    tg = lambda t: C(100) + 8 * (t - 100)
    return G(300, 230, [(curve(C, kx, ky), 0, 120 * kx, K.BLUE), (curve(tg, kx, ky), 60 * kx, 120 * kx, K.GREEN)], xt=[(kx * v, str(v)) for v in (40, 80, 120)], yt=[(ky * v, str(v)) for v in (300, 600, 900)],
             dots=[(100 * kx, C(100) * ky, '', 0, 0, K.RED)], xlabel='x', ylabel='C', pad=46)


def fig_rev():
    return fig_parab(lambda t: 120 * t - 0.4 * t * t, 300, 9500, xt=(100, 150, 200, 300), yt=(3000, 9000), peak=(150, 9000), xl='x', yl='R')


def fig_prof():
    return fig_parab(lambda t: -0.3 * t ** 2 + 30 * t - 200 if t > 0 else -200, 100, 700, xt=(25, 50, 75, 100), yt=(300, 550), peak=(50, 550), xl='x', yl='P')


def fig_avg(a, b, c, xmax, ymax, xt, yt, xmin):
    kx, ky = 250.0 / xmax, 170.0 / ymax
    f = lambda t: a * t + b + c / t
    return G(310, 220, [(curve(f, kx, ky), xmin * kx, xmax * kx, K.BLUE)], xt=[(kx * v, str(v)) for v in xt], yt=[(ky * v, str(v)) for v in yt], xlabel='x', ylabel='C̄', pad=46)


def fig_avg1():
    return fig_avg(0.02, 10, 800, 400, 60, (100, 200, 300, 400), (18, 40), 40)


def fig_avg2():
    return fig_avg(0.5, 20, 1250, 120, 160, (25, 50, 100), (70, 100), 12)


