def cands_writing():
    C = []
    f = lambda t: t ** 3
    chk(lambda: (close(D(f, 2) * mp.mpf('0.1'), mp.mpf('1.2')), close(f(mp.mpf('2.1')) - 8, mp.mpf('1.261'))))
    C.append(wr('easy', 's1', 'គេមាន ' + M('y=x^3') + ' ។ ក. គណនា ' + M('dy') + ' ត្រង់ ' + M('x=2') + ' និង ' + M('dx=0{,}1') + ' ។ ខ. គណនា ' + M('\\Delta y') + ' ។ គ. គណនា ' + M('dy-\\Delta y') + ' ។',
                [('ក. ' + M('f\'(x)=3x^2') + ' ដូច្នេះ ' + M('f\'(2)=12'), 1),
                 (M('dy=f\'(2)\\,dx=12\\times0{,}1=1{,}2'), 1),
                 ('ខ. ' + M('\\Delta y=f(2{,}1)-f(2)=(2{,}1)^3-2^3=9{,}261-8'), 1),
                 (M('\\Delta y=1{,}261'), 1),
                 ('គ. ' + M('dy-\\Delta y=1{,}2-1{,}261=-0{,}061') + ' (ដូច្នេះ ' + M('dy\\approx\\Delta y') + ' កាលណា ' + M('dx') + ' តូច)។', 1)], bloom='Apply'))
    v, tv = lin(mp.cbrt, 8, mp.mpf('0.12'))
    chk(lambda: (close(v, 2.01, 1e-9), abs(tv - v) < 1e-4))
    C.append(wr('medium', 's1', 'ប្រើឌីផេរ៉ង់ស្យែលរកតម្លៃប្រហែលនៃ ' + M('\\sqrt[3]{8{,}12}') + ' ហើយប្រៀបធៀបនឹងតម្លៃពិត ។',
                [('តាង ' + M('f(x)=\\sqrt[3]x') + ' ; ' + M('x=8') + ' និង ' + M('dx=0{,}12'), 1),
                 (M('f\'(x)=\\dfrac1{3\\sqrt[3]{x^2}}') + ' ដូច្នេះ ' + M('f\'(8)=\\dfrac1{3\\cdot4}=\\dfrac1{12}'), 1),
                 (M('dy=\\dfrac1{12}\\times0{,}12=0{,}01'), 1),
                 (M('\\sqrt[3]{8{,}12}\\approx f(8)+dy=2+0{,}01=2{,}01'), 1),
                 ('តម្លៃពិត ' + M('\\sqrt[3]{8{,}12}\\approx2{,}00997') + ' ដូច្នេះកំហុស ' + M('<0{,}0001') + '។', 1)], bloom='Apply'))
    Cc = lambda t: 0.1 * t ** 2 + 5 * t + 300
    chk(lambda: (close(Cc(51) - Cc(50), 15.1), close(D(Cc, 50), 15)))
    C.append(wr('medium', 's3', 'ប្រាក់ចំណាយ ' + M('C(x)=0{,}1x^2+5x+300') + ' ពាន់រៀល ។ ក. គណនា ' + M('C(51)-C(50)') + ' ។ ខ. គណនាប្រាក់ចំណាយម៉ាជីណាល ' + M('C\'(50)') + ' ។ គ. ប្រៀបធៀបលទ្ធផលទាំងពីរ ។',
                [('ក. ' + M('C(50)=250+250+300=800') + ' ពាន់រៀល', 1),
                 (M('C(51)=260{,}1+255+300=815{,}1') + ' ដូច្នេះ ' + M('C(51)-C(50)=15{,}1'), 1),
                 ('ខ. ' + M('C\'(x)=0{,}2x+5') + ' ដូច្នេះ ' + M('C\'(50)=15'), 1),
                 ('គ. ' + M('C\'(50)=15\\approx15{,}1=C(51)-C(50)'), 1),
                 ('ភាពខុស ' + M('0{,}1') + ' តូច ដូច្នេះប្រាក់ចំណាយម៉ាជីណាលជាតម្លៃប្រហែលល្អនៃប្រាក់ចំណាយឯកតាបន្ទាប់។', 1)], bloom='Apply'))
